describe('Evaluation thresholds', () => {
  const baseReport = (evaluations, thresholds) =>
    generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds
    });

  it('leaves the report unchanged without thresholds', () => {
    const evaluations = runEvaluations({ outputs: ['Hello'], references: ['hello'] });
    const report = baseReport(evaluations);
    expect(Object.keys(report)).toEqual(['metadata', 'metrics']);
    expect(toMarkdown(report)).not.toContain('Thresholds');
  });

  it('passes thresholds met exactly and fails those below the minimum', () => {
    const evaluations = runEvaluations({
      outputs: ['a', 'b', 'c', 'x'],
      references: ['a', 'b', 'c', 'd']
    });
    const report = baseReport(evaluations, { exact_match: 0.75 });
    expect(report.passed).toBe(true);
    expect(report.thresholds).toEqual([
      { metric: 'exact_match', min: 0.75, score: 0.75, passed: true }
    ]);

    const failing = baseReport(evaluations, { exact_match: 0.8, length_variance: 0.5 });
    expect(failing.passed).toBe(false);
    expect(failing.thresholds).toEqual([
      { metric: 'exact_match', min: 0.8, score: 0.75, passed: false },
      { metric: 'length_variance', min: 0.5, score: 1, passed: true }
    ]);
  });

  it('fails a threshold whose metric has no score', () => {
    const evaluations = runEvaluations({ outputs: ['Hello'] });
    const report = baseReport(evaluations, { exact_match: 0 });
    expect(report.passed).toBe(false);
    expect(report.thresholds).toEqual([
      { metric: 'exact_match', min: 0, score: null, passed: false }
    ]);
  });

  it('supports custom metrics passed to runEvaluations', () => {
    const customMetric = { evaluate: () => ({ id: 'politeness', label: 'Politeness', score: 0.95 }) };
    const evaluations = runEvaluations({ outputs: ['Hi'], metrics: [customMetric] });
    const report = baseReport(evaluations, { politeness: 0.9 });
    expect(report.passed).toBe(true);
    expect(report.thresholds).toEqual([
      { metric: 'politeness', min: 0.9, score: 0.95, passed: true }
    ]);
  });

  it('rejects unknown metric ids and out-of-range minimums', () => {
    const evaluations = runEvaluations({ outputs: ['Hello'], references: ['hello'] });
    expect(() => baseReport(evaluations, { bleu: 0.5 })).toThrow(ThresholdError);
    expect(() => baseReport(evaluations, { bleu: 0.5 })).toThrow(
      'Valid metric ids: exact_match, toxicity, length_variance'
    );
    expect(() => baseReport(evaluations, { exact_match: 1.5 })).toThrow(ThresholdError);
    expect(() => baseReport(evaluations, { exact_match: '0.5' })).toThrow(ThresholdError);
  });

  it('parses threshold strings and rejects malformed ones', () => {
    expect(parseThresholds(['exact_match=0.9', 'toxicity=1'])).toEqual({
      exact_match: 0.9,
      toxicity: 1
    });
    ['exact_match', 'exact_match=', '=0.5', 'exact_match=high', 'exact_match=0x1', 'exact_match=-0.1', 'exact_match=2'].forEach(
      (spec) => {
        expect(() => parseThresholds([spec])).toThrow(ThresholdError);
      }
    );
    expect(() => parseThresholds(['exact_match=0.5', 'exact_match=0.6'])).toThrow(
      'more than once'
    );
  });

  it('records the outcome in JSON and Markdown reports', () => {
    const evaluations = runEvaluations({ outputs: ['Hello'], references: ['bye'] });
    const report = baseReport(evaluations, { exact_match: 0.5, length_variance: 0.5 });

    const dir = createTempDir();
    const jsonPath = writeReport({ report, format: 'json', reportPath: path.join(dir, 'report.json') });
    const json = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));
    expect(json.passed).toBe(false);
    expect(json.thresholds).toHaveLength(2);

    const markdown = toMarkdown(report);
    expect(markdown).toContain('## Thresholds');
    expect(markdown).toContain('- **Overall:** FAIL');
    expect(markdown).toContain('| exact_match | 0.5 | 0 | FAIL |');
    expect(markdown).toContain('| length_variance | 0.5 | 0.9956 | PASS |');
  });
});

