import { spawnSync } from 'child_process';
import fs from 'fs';
import path from 'path';

const CLI = '/private/tmp/100-tricks-runs/pilot-hard/without/h2-eval-thresholds/r1/packages/frai-cli/dist/index.js';
const dir = '/tmp/frai-e2e';
const out = path.join(dir, 'out.json');
const ref = path.join(dir, 'ref.json');
const reports = path.join(dir, 'reports');
fs.rmSync(reports, { recursive: true, force: true });
fs.mkdirSync(reports);

const run = (label, args) => {
  const result = spawnSync(process.execPath, [CLI, 'eval', ...args], { encoding: 'utf8' });
  console.log(`--- ${label}: exit=${result.status}`);
  console.log((result.stdout + result.stderr).replace(/^\[[^\]]+\] /gm, '').trim());
};
const r = (name) => path.join(reports, name);

run('no thresholds', ['--outputs', out, '--references', ref, '--report', r('base.json')]);
console.log(Object.keys(JSON.parse(fs.readFileSync(r('base.json'), 'utf8'))));

run('passing', ['--outputs', out, '--references', ref, '--threshold', 'exact_match=0.75', '--threshold', 'length_variance=0.5', '--report', r('pass.json')]);
const pass = JSON.parse(fs.readFileSync(r('pass.json'), 'utf8'));
console.log(pass.passed, JSON.stringify(pass.thresholds));

run('failing markdown', ['--outputs', out, '--references', ref, '--threshold', 'exact_match=0.9', '--format', 'markdown', '--report', r('fail.md')]);
const md = fs.readFileSync(r('fail.md'), 'utf8');
console.log(md.slice(md.indexOf('## Thresholds')));

run('no references', ['--outputs', out, '--threshold', 'exact_match=0', '--report', r('noref.json')]);
const noref = JSON.parse(fs.readFileSync(r('noref.json'), 'utf8'));
console.log(noref.passed, JSON.stringify(noref.thresholds));

run('malformed', ['--outputs', out, '--references', ref, '--threshold', 'exact_match', '--report', r('bad1.json')]);
run('out of range', ['--outputs', out, '--references', ref, '--threshold', 'exact_match=1.2', '--report', r('bad2.json')]);
run('unknown metric', ['--outputs', out, '--references', ref, '--threshold', 'bleu=0.5', '--report', r('bad3.json')]);
run('non-number (= form)', ['--outputs', out, '--references', ref, '--threshold=exact_match=abc', '--report', r('bad4.json')]);
run('duplicate', ['--outputs', out, '--threshold', 'exact_match=0.5', '--threshold', 'exact_match=0.6', '--report', r('bad5.json')]);

console.log('reports written:', fs.readdirSync(reports));

